function removeChildren(node, index = 0) {
  const nodes = node.childNodes;
  let i = nodes.length;
  while (i > index) node.removeChild(nodes[--i]);
}

class ArticleElement extends s {
  createRenderRoot() {
    return this;
  }

  connectedCallback() {
    if (!this.__initchildnodes) {
      this.__initchildnodes = true;
      this.initialChildNodes(Array.from(this.childNodes));
      removeChildren(this);
    }
    super.connectedCallback();
  }

  initialChildNodes(nodes) {
    this.__children = nodes;
  }
}

class CiteRef extends ArticleElement {

  static get properties() {
    return {
      key: {type: String},
      mode: {type: String},
      index: {type: Number},
      data: {type: Object}
    };
  }

  constructor() {
    super();
    this.mode = 'citation';
    this.addEventListener('keydown', this.keyDown);
    this.addEventListener('mousedown', this.openCitation);
    this.addEventListener('focusout', this.focusOut);
  }

  focusOut(event) {
    if (!this.contains(event.relatedTarget)) {
      this.closeCitation();
    }
  }

  keyDown(event) {
    if (event.key == 'Enter') {
      this.openCitation();
    } else if (event.key != 'Tab') {
      this.closeCitation();
    }
  }

  closeCitation() {
    for (const child of this.querySelector('.cite-ref').children) {
      child.style.display = 'none';
    }
  }

  openCitation() {
    for (const child of this.querySelector('.cite-ref').children) {
      child.style.display = 'inline-block';
    }
  }

  // Expand and collapse info content
  toggleContent(event) {
    const summary = event.target.firstChild;
    event.target.hasAttribute('open')
      ? summary.textContent = summary.getAttribute('data-longtext')
      : summary.textContent = summary.getAttribute('data-shorttext');
  }

  initialChildNodes(nodes) {
    this.__prefix = nodes[0];
    this.__suffix = nodes[1];
  }

  render() {
    const { key, data, index, mode} = this;
    const wrapper = $`<div class='cite-info-wrapper'></div>`;

    // Unresolved citation
    if (data == null) {
      return $`<span class='cite-ref unresolved'>??${wrapper}<div class='cite-info'>
        <b>Unresolved citation</b><br>"${key}"</div></span>`;
    }

    const { fullInfo, shortInfo } = infoBody(data);
    const desctext = descBody(data);

    // Citation contents
    const subtitle = data.venue ? $`<div class='cite-head-subtitle'>${data.venue}</div>` : null;
    const info = shortInfo
      ? $`<details class='cite-body-auth' @toggle=${this.toggleContent}>
              <summary data-shorttext=${shortInfo} data-longtext=${fullInfo}>${shortInfo}</summary>
            </details>`
      : $`<div class='cite-body-auth'>${fullInfo}</div>`;
    const desc = data.abstract && data.abstract !== desctext
      ? $`<details class='cite-body-desc' @toggle=${this.toggleContent}>
              <summary data-shorttext=${desctext} data-longtext=${data.abstract}>${desctext}</summary>
            </details>`
      : $`<div class='cite-body-desc'>${desctext}</div>`;

    // Inline content
    const body = mode === 'inline-author' ? inlineContent(data, index) : index;

    return $`<span class='cite-ref' tabindex=0>${body}${wrapper}<div class='cite-info'>
      <a class='cite-head' href=${data.url} target="_blank" rel="noopener noreferrer" style="color: inherit;">
        <div class='cite-head-title'>${data.title}</div>${subtitle}
      </a>
      <div class='cite-body'>
        ${info}${desc}
      </div>
    </div></span>`;
  }
}

// Returns inline authors, or abbrev. if there are more than etal authors
function inlineContent(data, index, etal=2) {
  const { author } = data;

  let authors = author[0].family;
  if (author.length === 2) {
    authors += ` & ${author[1].family}`;
  } else if (author.length > etal) {
    authors += ' et al.';
  }

  return `${authors} [${index}]`;
}

function infoBody(data, maxAuthors=2) {
  const { author, year } =  data;

  const aMap = author.map(({ given, family }) => {
    if (!given) { return family; }
    return `${given.includes('.') ? given:given[0] + '.'} ${family}`;
  });
  const fullInfo = `${year} \u2022 ${aMap.join(', ')}`;
  const shortInfo = aMap.length > maxAuthors
    ? `${year} \u2022 ${aMap.slice(0, maxAuthors).join(', ')} +${aMap.length - maxAuthors}`
    : null;

  return {fullInfo, shortInfo};
}

function descBody(data, charLimit=300) {
  const { abstract, tldr } = data;

  const shortDesc = tldr || abstract || 'No description is available for this article.';

  return shortDesc.length > charLimit
    ? shortDesc.substring(0, shortDesc.substring(0, charLimit).lastIndexOf(' ')) + '... '
    : shortDesc;
}

class CrossRef extends ArticleElement {
  static get properties() {
    return {
      type: {type: String},
      xref: {type: String},
      index: {type: Number},
      short: {type: Boolean},
    };
  }

  goto(event) {
    // prevent jump to referenced element
    event.preventDefault();

    // add id to hash component of current URL
    // do not change the page undo history
    const id =`#${this.xref}`;
    history.replaceState(null, null, id);

    // smoothly scroll to referenced component
    document.querySelector(id)
      .scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }

  render() {
    // TODO? title tooltip
    const { type, xref, index, short } = this;
    const resolved = index != null;
    const cls = `cross-ref ${type}${!short ? ' full' : ''}`;
    if (resolved) {
      return $`<a class=${cls} href="#${xref}" @click=${this.goto}>${index}</a>`;
    } else {
      return $`<a class="${cls} unresolved" title="Unresolved reference: ${xref}">?</a>`;
    }
  }
}

let numNotes = 0; // incrementing counter of notes

class InlineNote extends ArticleElement {
  constructor() {
    super();
    this.number = ++numNotes;
  }

  render() {
    const num = this.number;
    return $`<span class="inline-note" @click=${(evt) => evt.target.parentElement.classList.toggle('open')}>
      <sup class="inline-note-number">${num}</sup>
      <span class="note margin" data-number="${num}">${this.__children}</span>
    </span>`;
  }
}

function reference(root, refdata) {
  root.querySelectorAll('cite-ref').forEach(cite => {
    if (cite.index != null) {
      cite.data = refdata[cite.index - 1];
    }
  });
}

window.customElements.define('cite-ref', CiteRef);
window.customElements.define('cross-ref', CrossRef);
window.customElements.define('inline-note', InlineNote);

window.setUpReferences = () => {
  const root = document.querySelector('body');
  reference(root, [{"id":"doi:10.1145/3428290","doi":"10.1145/3428290","s2id":"12243d14abcafac95103ff4d2ea5e030f2ee8eb3","year":2020,"author":[{"ORCID":"http://orcid.org/0000-0002-6179-7784","authenticated-orcid":false,"given":"Leif","family":"Andersen","sequence":"first","affiliation":[{"name":"Northeastern University, USA"}]},{"given":"Michael","family":"Ballantyne","sequence":"additional","affiliation":[{"name":"Northeastern University, USA"}]},{"given":"Matthias","family":"Felleisen","sequence":"additional","affiliation":[{"name":"Northeastern University, USA"}]}],"title":"Adding interactive visual syntax to textual code: ","venue":"Proceedings of the ACM on Programming Languages","url":"https://www.semanticscholar.org/paper/12243d14abcafac95103ff4d2ea5e030f2ee8eb3","abstract":"Many programming problems call for turning geometrical thoughts into code: tables, hierarchical structures, nests of objects, trees, forests, graphs, and so on. Linear text does not do justice to such thoughts. But, it has been the dominant programming medium for the past and will remain so for the foreseeable future. This paper proposes a novel mechanism for conveniently extending textual programming languages with problem-specific visual syntax. It argues the necessity of this language feature, demonstrates the feasibility with a robust prototype, and sketches a design plan for adapting the idea to other languages.","tldr":"This paper proposes a novel mechanism for conveniently extending textual programming languages with problem-specific visual syntax, and argues the necessity of this language feature, demonstrates the feasibility with a robust prototype, and sketches a design plan for adapting the idea to other languages."},{"id":"doi:10.1184/R1/6714389.V1","doi":"10.1184/R1/6714389.V1","s2id":"9d99869f5a7845e81884ef4f425bbbf16364b962","year":2016,"author":[{"family":"Chang","given":"Kerry Shih-Ping"}],"title":"A Spreadsheet Model for Using Web Services and Creating Data-Driven Applications","venue":"Carnegie Mellon University","url":"https://www.semanticscholar.org/paper/9d99869f5a7845e81884ef4f425bbbf16364b962","abstract":"iii Acknowledgements iv Table Of"},{"id":"DBLP:journals/aim/Lau09","doi":"10.1609/aimag.v30i4.2262","s2id":"37c50b0cc3c701b269c18014dd3a0c07f9c2b4b8","year":2009,"author":[{"given":"Tessa","family":"Lau"}],"title":"Why Programming-By-Demonstration Systems Fail: Lessons Learned for Usable AI","venue":"AI Mag.","url":"https://www.semanticscholar.org/paper/37c50b0cc3c701b269c18014dd3a0c07f9c2b4b8","abstract":"Programming by demonstration systems have long attempted to make it possible for people to program computers without writing code. However, while these systems have resulted in many publications in AI venues, none of the technologies have yet achieved widespread.adoption. Usability remains a critical barrier to their success. On the basis of lessons learned from three different programming by demonstration systems, we present a set of guidelines to consider when designing usable AI-based systems.","tldr":"On the basis of lessons learned from three different programming by demonstration systems, a set of guidelines to consider when designing usable AI-based systems is presented."},{"id":"doi:10.1145/1052883.1052894","doi":"10.1145/1052883.1052894","s2id":"5d072e2a26997eb0c966f9a31f038baca00101f3","year":2004,"author":[{"given":"Jonathan","family":"Edwards","sequence":"first","affiliation":[{"name":"MIT CSAIL, Cambridge, MA"}]}],"title":"Example centric programming: ","venue":"ACM SIGPLAN Notices","url":"https://www.semanticscholar.org/paper/5d072e2a26997eb0c966f9a31f038baca00101f3","abstract":"Programmers tend to understand programs by thinking of concrete examples. Example Centric Programming seeks to add IDE support for examples throughout the process of programming. Instead of programmers interpreting examples in their head, the examples are written down and the IDE interprets them automatically. Advanced UI techniques are used to present the results closely integrated with the code. Traditionally distinct programming tools (the editor, Read-Eval-Print-Loop, debugger, and test runner) are unified into a single tool that might be called an example-enlightened editor. This is expected to benefit a wide spectrum of programming activities, for both novice and experienced programmers. Some novel methods for testing and development are made possible. In the longer term, example centrism has implications for the design of future programming languages. A prototype has been implemented for Java in Eclipse.","tldr":"Examples Centric Programming seeks to add IDE support for examples throughout the process of programming, instead of programmers interpreting examples in their head, the examples are written down and the IDE interprets them automatically."},{"id":"doi:10.1145/1094811.1094851","doi":"10.1145/1094811.1094851","s2id":"fd192eee394577fb6a2a6a8a59cdab85a40faaa5","year":2005,"author":[{"given":"Jonathan","family":"Edwards","sequence":"first","affiliation":[]}],"title":"Subtext: uncovering the simplicity of programming","venue":"Proceedings of the 20th annual ACM SIGPLAN conference on Object oriented programming systems languages and applications  - OOPSLA '05","url":"https://www.semanticscholar.org/paper/fd192eee394577fb6a2a6a8a59cdab85a40faaa5","abstract":"Representing programs as text strings makes programming harder then it has to be. The source text of a program is far removed from its behavior. Bridging this conceptual gulf is what makes programming so inhumanly difficult -- we are not compilers. Subtext is a new medium in which the representation of a program is the same thing as its execution. Like a spreadsheet, a program is visible and alive, constantly executing even as it is edited. Program edits are coherent semantic transformations.The essence of this new medium is copying. Programs are constructed by copying and executed by copy flow: the projection of changes through copies. The simple idea of copying develops into a rich theory of higher-order continual copying of trees. Notably absent are symbolic names, the workhorse of textual notation, replaced by immediately-bound explicit relationships. Subtext unifies traditionally distinct programming tools and concepts, and enables some novel ones. Ancestral structures are a new primitive data type that combines the features of lists and records, along with unproblematic multiple inheritance. Adaptive conditionals use first-class program edits to dynamically adapt behavior.A prototype implementation shows promise, but calls for much further research. Subtext suggests that we can make programming radically easier, if we are willing to be radical.","tldr":"Subtext is a new medium in which the representation of a program is the same thing as its execution, and unifies traditionally distinct programming tools and concepts, and enables some novel ones."},{"id":"doi:10.7249/RM6001","doi":"10.7249/rm6001","s2id":"16324e5441150915489e698f3671498da24198d9","year":1969,"author":[{"given":"T.","family":"Ellis","sequence":"first","affiliation":[]},{"given":"J.","family":"Heafner","sequence":"first","affiliation":[]},{"given":"W.","family":"Sibley","sequence":"first","affiliation":[]}],"title":"The GRAIL Language and Operations: ","venue":[],"url":"https://www.semanticscholar.org/paper/16324e5441150915489e698f3671498da24198d9","abstract":"Abstract : The important organizational concepts of the flowchart language are the sequential flow of control, the hierarchy of subroutines, and the language (flow diagrams) that pictorially relates their interdependence. A fundamental facility of the man-machine interface is the automatic recognition of appropriate symbols, which allows the man to print or draw appropriate symbols freehand. GRAIL's text-editing features include placement, replacement, and deletion of characters, character-string insertion of deletion, and line deletion. Control functions include displaying text page-by-page, requesting specified display frames, moving symbols, and text line editing. The flowchart processes may be compiled and executed at CPU speeds or the man may control interpretative execution by direct stylus actions. He may use overlay displays or split screen displays to debug. This is the second part of a final report on GRAIL.","tldr":"GRAIL's text-editing features include placement, replacement, and deletion of characters, character-string insertion of deletion, and line deletion, while control functions include displaying text page-by-page, requesting specified display frames, moving symbols, and text line editing."},{"id":"Ellis1969THEGP","year":1969,"author":[{"given":"T. O.","family":"Ellis"},{"given":"John F.","family":"Heafner"},{"given":"William L.","family":"Sibley"}],"title":"THE GRAIL PROJECT: AN EXPERIMENT IN MAN-MACHINE COMMUNICATIONS","url":"https://www.rand.org/pubs/research_memoranda/RM5999.html"},{"id":"doi:10.1145/3379337.3415869","doi":"10.1145/3379337.3415869","s2id":"cb7ecee937f3aed98a9ce50e0881e43a60270466","year":2020,"author":[{"given":"Kasra","family":"Ferdowsifard","sequence":"first","affiliation":[{"name":"University of California, San Diego, La Jolla, CA, USA"}]},{"given":"Allen","family":"Ordookhanians","sequence":"additional","affiliation":[{"name":"University of California, San Diego, La Jolla, CA, USA"}]},{"given":"Hila","family":"Peleg","sequence":"additional","affiliation":[{"name":"University of California, San Diego, La Jolla, CA, USA"}]},{"given":"Sorin","family":"Lerner","sequence":"additional","affiliation":[{"name":"University of California, San Diego, La Jolla, CA, USA"}]},{"given":"Nadia","family":"Polikarpova","sequence":"additional","affiliation":[{"name":"University of California, San Diego, La Jolla, CA, USA"}]}],"title":"Small-Step Live Programming by Example: ","venue":"Proceedings of the 33rd Annual ACM Symposium on User Interface Software and Technology","url":"https://www.semanticscholar.org/paper/cb7ecee937f3aed98a9ce50e0881e43a60270466","abstract":"Live programming is a paradigm in which the programming environment continually displays runtime values. Program synthesis is a technique that can generate programs or program snippets from examples. \\deltextThis paper presents a new programming paradigm called Synthesis-Aided Live Programming that combines these two prior ideas in a synergistic way. When using Synthesis-Aided Live Programming, programmers can change the runtime values displayed by the live \\addtextPrevious works that combine the two have taken a holistic approach to the way examples describe the behavior of functions and programs. This paper presents a new programming paradigm called Small-Step Live Programming by Example that lets the user apply Programming by Example locally. When using Small-Step Live Programming by Example, programmers can change the runtime values displayed by the live visualization to generate local program snippets. % Live programming and program % synthesis work perfectly together because the live programming environment % reifies values, which makes it easy for programmers to provide the examples % needed by the synthesizer. We implemented this new paradigm in a tool called \\toolname, and performed a user study on $13$ programmers. Our study finds that Small-Step Live Programming by Example with \\toolname helps users solve harder problems faster, and that for certain types of queries, users prefer it to searching the web. Additionally, we identify the \\usersynthgap, in which users' mental models of the tool do not match its ability, and needs to be taken into account in the design of future synthesis tools.","tldr":"This study finds that Small-Step Live Programming by Example with \\toolname helps users solve harder problems faster, and that for certain types of queries, users prefer it to searching the web."},{"id":"doi:10.1145/2814189.2817268","doi":"10.1145/2814189.2817268","s2id":"dccb116e4f7b2c1cf15be238693415a44a7e3881","year":2015,"author":[{"given":"Tomoki","family":"Imai","sequence":"first","affiliation":[{"name":"Tokyo Institute of Technology, Japan"}]},{"given":"Hidehiko","family":"Masuhara","sequence":"additional","affiliation":[{"name":"Tokyo Institute of Technology, Japan"}]},{"given":"Tomoyuki","family":"Aotani","sequence":"additional","affiliation":[{"name":"Tokyo Institute of Technology, Japan"}]}],"title":"Shiranui: a live programming with support for unit testing: ","venue":"Companion Proceedings of the 2015 ACM SIGPLAN International Conference on Systems, Programming, Languages and Applications: Software for Humanity","url":"https://www.semanticscholar.org/paper/dccb116e4f7b2c1cf15be238693415a44a7e3881","abstract":"Live programming environments help the programmers to try out expressions by giving immediate feedback on the results as well as intermediate evaluation processes. However, the feedback is transient, and its correctness is merely confirmed by the programmers' manual inspection. We seamlessly integrate live programming with unit testing by proposing novel features (1) that converts a lively-tested expression into a unit test case, and (2) that extracts a unit test case from an execution trace of a lively-tested expression. In this poster, we overview Shiranui, our live programming environment, and present the proposed features implemented in Shiranui.","tldr":"This paper seamlessly integrate live programming with unit testing by proposing novel features (1) that converts a lively-tested expression into a unit test case, and (2) that extracts aunit test case from an execution trace of an lively- tested expression."},{"id":"doi:10.1145/1978942.1979444","doi":"10.1145/1978942.1979444","s2id":"4c67851b77766ba4ad9f1ac0bd4c9491c327574e","year":2011,"author":[{"given":"Sean","family":"Kandel","sequence":"first","affiliation":[{"name":"Stanford University, Stanford, California, USA"}]},{"given":"Andreas","family":"Paepcke","sequence":"additional","affiliation":[{"name":"Stanford University, Stanford, California, USA"}]},{"given":"Joseph","family":"Hellerstein","sequence":"additional","affiliation":[{"name":"University of California, Berkeley, Berkeley, California, USA"}]},{"given":"Jeffrey","family":"Heer","sequence":"additional","affiliation":[{"name":"Stanford University, Stanford, California, USA"}]}],"title":"Wrangler: interactive visual specification of data transformation scripts","venue":"Proceedings of the SIGCHI Conference on Human Factors in Computing Systems","url":"https://www.semanticscholar.org/paper/4c67851b77766ba4ad9f1ac0bd4c9491c327574e","abstract":"Though data analysis tools continue to improve, analysts still expend an inordinate amount of time and effort manipulating data and assessing data quality issues. Such \"data wrangling\" regularly involves reformatting data values or layout, correcting erroneous or missing values, and integrating multiple data sources. These transforms are often difficult to specify and difficult to reuse across analysis tasks, teams, and tools. In response, we introduce Wrangler, an interactive system for creating data transformations. Wrangler combines direct manipulation of visualized data with automatic inference of relevant transforms, enabling analysts to iteratively explore the space of applicable operations and preview their effects. Wrangler leverages semantic data types (e.g., geographic locations, dates, classification codes) to aid validation and type conversion. Interactive histories support review, refinement, and annotation of transformation scripts. User study results show that Wrangler significantly reduces specification time and promotes the use of robust, auditable transforms instead of manual editing.","tldr":"Wrangler combines direct manipulation of visualized data with automatic inference of relevant transforms, enabling analysts to iteratively explore the space of applicable operations and preview their effects."},{"id":"doi:10.1145/3379337.3415842","doi":"10.1145/3379337.3415842","s2id":"21ea5e0048b34ef870c91594581fabd5d98315af","year":2020,"author":[{"given":"Mary Beth","family":"Kery","sequence":"first","affiliation":[{"name":"Carnegie Mellon University, Pittsburgh, PA, USA"}]},{"given":"Donghao","family":"Ren","sequence":"additional","affiliation":[{"name":"Apple Inc., Seattle, WA, USA"}]},{"given":"Fred","family":"Hohman","sequence":"additional","affiliation":[{"name":"Georgia Institute of Technology, Atlanta, GA, USA"}]},{"given":"Dominik","family":"Moritz","sequence":"additional","affiliation":[{"name":"Apple Inc., Seattle, WA, USA"}]},{"given":"Kanit","family":"Wongsuphasawat","sequence":"additional","affiliation":[{"name":"Apple Inc., Seattle, WA, USA"}]},{"given":"Kayur","family":"Patel","sequence":"additional","affiliation":[{"name":"Apple Inc, Seattle, WA, USA"}]}],"title":"mage: Fluid Moves Between Code and Graphical Work in Computational Notebooks: ","venue":"Proceedings of the 33rd Annual ACM Symposium on User Interface Software and Technology","url":"https://www.semanticscholar.org/paper/21ea5e0048b34ef870c91594581fabd5d98315af","abstract":"We aim to increase the flexibility at which a data worker can choose the right tool for the job, regardless of whether the tool is a code library or an interactive graphical user interface (GUI). To achieve this flexibility, we extend computational notebooks with a new API mage, which supports tools that can represent themselves as both code and GUI as needed. We discuss the design of mage as well as design opportunities in the space of flexible code/GUI tools for data work. To understand tooling needs, we conduct a study with nine professional practitioners and elicit their feedback on mage and potential areas for flexible code/GUI tooling. We then implement six client tools for mage that illustrate the main themes of our study findings. Finally, we discuss open challenges in providing flexible code/GUI interactions for data workers.","tldr":"This work extends computational notebooks with a new API mage, which supports tools that can represent themselves as both code and GUI as needed, and implements six client tools for mage that illustrate the main themes of the study findings."},{"id":"doi:10.1145/3313831.3376494","doi":"10.1145/3313831.3376494","s2id":"57e3ad7c294490947caf75cc19070453019f78f7","year":2020,"author":[{"given":"Sorin","family":"Lerner","sequence":"first","affiliation":[{"name":"University of California, San Diego, La Jolla, CA, USA"}]}],"title":"Projection Boxes: On-the-fly Reconfigurable Visualization for Live Programming: ","venue":"Proceedings of the 2020 CHI Conference on Human Factors in Computing Systems","url":"https://www.semanticscholar.org/paper/57e3ad7c294490947caf75cc19070453019f78f7","abstract":"Live programming is a regime in which the programming environment provides continual feedback, most often in the form of runtime values. In this paper, we present Projection Boxes, a novel visualization technique for displaying runtime values of programs. The key idea behind projection boxes is to start with a full semantics of the program, and then use projections to pick a subset of the semantics to display. By varying the projection used, projection boxes can encode both previously known visualization techniques, and also new ones. As such, projection boxes provide an expressive and configurable framework for displaying runtime information. Through a user study we demonstrate that (1) users find projection boxes and their configurability useful (2) users are not distracted by the always-on visualization (3) a key driving force behind the need for a configurable visualization for live programming lies with the wide variation in programmer preferences.","tldr":"This paper presents Projection Boxes, a novel visualization technique for displaying runtime values of programs, and demonstrates that users find projection boxes and their configurability useful and users are not distracted by the always-on visualization."},{"id":"doi:10.1145/3173574.3173697","doi":"10.1145/3173574.3173697","s2id":"26d45d8bc58bfb43d3c4603321b8201219a08e32","year":2018,"author":[{"given":"Zhicheng","family":"Liu","sequence":"first","affiliation":[{"name":"Adobe Research, Seattle, WA, USA"}]},{"given":"John","family":"Thompson","sequence":"additional","affiliation":[{"name":"Georgia Institute of Technology, Atlanta, GA, USA"}]},{"given":"Alan","family":"Wilson","sequence":"additional","affiliation":[{"name":"Adobe Systems Inc., Lehi, UT, USA"}]},{"given":"Mira","family":"Dontcheva","sequence":"additional","affiliation":[{"name":"Adobe Research, Seattle, WA, USA"}]},{"given":"James","family":"Delorey","sequence":"additional","affiliation":[{"name":"Adobe Systems Inc., Lehi, UT, USA"}]},{"given":"Sam","family":"Grigg","sequence":"additional","affiliation":[{"name":"Adobe Systems Inc., Lehi, UT, USA"}]},{"given":"Bernard","family":"Kerr","sequence":"additional","affiliation":[{"name":"Adobe Systems Inc., San Francisco, CA, USA"}]},{"given":"John","family":"Stasko","sequence":"additional","affiliation":[{"name":"Georgia Institute of Technology, Atlanta, GA, USA"}]}],"title":"Data Illustrator: Augmenting Vector Design Tools with Lazy Data Binding for Expressive Visualization Authoring","venue":"Proceedings of the 2018 CHI Conference on Human Factors in Computing Systems","url":"https://www.semanticscholar.org/paper/26d45d8bc58bfb43d3c4603321b8201219a08e32","abstract":"Building graphical user interfaces for visualization authoring is challenging as one must reconcile the tension between flexible graphics manipulation and procedural visualization generation based on a graphical grammar or declarative languages. To better support designers' workflows and practices, we propose Data Illustrator, a novel visualization framework. In our approach, all visualizations are initially vector graphics; data binding is applied when necessary and only constrains interactive manipulation to that data bound property. The framework augments graphic design tools with new concepts and operators, and describes the structure and generation of a variety of visualizations. Based on the framework, we design and implement a visualization authoring system. The system extends interaction techniques in modern vector design tools for direct manipulation of visualization configurations and parameters. We demonstrate the expressive power of our approach through a variety of examples. A qualitative study shows that designers can use our framework to compose visualizations.","tldr":"Data Illustrator is proposed, a novel visualization framework that extends interaction techniques in modern vector design tools for direct manipulation of visualization configurations and parameters and demonstrates the expressive power of the approach through a variety of examples."},{"id":"doi:10.1145/22627.22349","doi":"10.1145/22627.22349","s2id":"0d5d9c7bff298475cc2e0d0c9d06465ecd7b3d13","year":1986,"author":[{"given":"B. A.","family":"Myers","sequence":"first","affiliation":[]}],"title":"Visual programming, programming by example, and program visualization: a taxonomy: ","venue":"Proceedings of the SIGCHI conference on Human factors in computing systems  - CHI '86","url":"https://www.semanticscholar.org/paper/0d5d9c7bff298475cc2e0d0c9d06465ecd7b3d13","abstract":"There has been a great interest recently in systems that use graphics to aid in the programming, debugging, and understanding of computer programs. The terms “Visual Programming” and “Program Visualization” have been applied to these systems. Also, there has been a renewed interest in using examples to help alleviate the complexity of programming. This technique is called “Programming by Example.” This paper attempts to provide more meaning to these terms by giving precise definitions, and then uses these definitions to classify existing systems into a taxonomy. A number of common unsolved problems with most of these systems are also listed.","tldr":"This paper attempts to provide more meaning to Visual Programming and Program Visualization terms by giving precise definitions, and then uses these definitions to classify existing systems into a taxonomy."},{"id":"doi:10.1109/VLHCC.2011.6070422","doi":"10.1109/vlhcc.2011.6070422","s2id":"8f3890d16756f0a7f90c002c8b8de4eed759c925","year":2011,"author":[{"given":"C.","family":"Omar","sequence":"first","affiliation":[]},{"family":"YoungSeok Yoon","sequence":"additional","affiliation":[]},{"given":"T. D.","family":"LaToza","sequence":"additional","affiliation":[]},{"given":"B. A.","family":"Myers","sequence":"additional","affiliation":[]}],"title":"Active code completion: ","venue":"2011 IEEE Symposium on Visual Languages and Human-Centric Computing (VL/HCC)","url":"https://www.semanticscholar.org/paper/8f3890d16756f0a7f90c002c8b8de4eed759c925","abstract":"Code completion menus have replaced standalone API browsers for most developers because they are more tightly integrated into the development workflow. Refinements to the code completion menu that incorporate additional sources of information have similarly been shown to be valuable, even relative to standalone counterparts offering similar functionality. In this paper, we describe active code completion, an architecture that allows library developers to introduce interactive and highly-specialized code generation interfaces, called palettes, directly into the editor. Using several empirical methods, we examine the contexts in which such a system could be useful, describe the design constraints governing the system architecture as well as particular code completion interfaces, and design one such system, named Graphite, for the Eclipse Java development environment. Using Graphite, we implement a palette for writing regular expressions as our primary example and conduct a small pilot study. In addition to showing the feasibility of this approach, it provides further evidence in support of the claim that integrating specialized code completion interfaces directly into the editor is valuable to professional developers.","tldr":"Active code completion is described, an architecture that allows library developers to introduce interactive and highly-specialized code generation interfaces, called palettes, directly into the editor, and one such system is designed, named Graphite, for the Eclipse Java development environment."},{"id":"doi:10.1145/3290327","doi":"10.1145/3290327","s2id":"0883204dc486793e777a025a7bc129da886a54b3","year":2018,"author":[{"given":"Cyrus","family":"Omar","sequence":"first","affiliation":[{"name":"University of Chicago, USA"}]},{"given":"Ian","family":"Voysey","sequence":"additional","affiliation":[{"name":"Carnegie Mellon University, USA"}]},{"given":"Ravi","family":"Chugh","sequence":"additional","affiliation":[{"name":"University of Chicago, USA"}]},{"given":"Matthew A.","family":"Hammer","sequence":"additional","affiliation":[{"name":"University of Colorado Boulder, USA"}]}],"title":"Live functional programming with typed holes: ","venue":"Proceedings of the ACM on Programming Languages","url":"https://www.semanticscholar.org/paper/0883204dc486793e777a025a7bc129da886a54b3","abstract":"Live programming environments aim to provide programmers (and sometimes audiences) with continuous feedback about a program's dynamic behavior as it is being edited. The problem is that programming languages typically assign dynamic meaning only to programs that are complete, i.e. syntactically well-formed and free of type errors. Consequently, live feedback presented to the programmer exhibits temporal or perceptive gaps. This paper confronts this \"gap problem\" from type-theoretic first principles by developing a dynamic semantics for incomplete functional programs, starting from the static semantics for incomplete functional programs developed in recent work on Hazelnut. We model incomplete functional programs as expressions with holes, with empty holes standing for missing expressions or types, and non-empty holes operating as membranes around static and dynamic type inconsistencies. Rather than aborting when evaluation encounters any of these holes as in some existing systems, evaluation proceeds around holes, tracking the closure around each hole instance as it flows through the remainder of the program. Editor services can use the information in these hole closures to help the programmer develop and confirm their mental model of the behavior of the complete portions of the program as they decide how to fill the remaining holes. Hole closures also enable a fill-and-resume operation that avoids the need to restart evaluation after edits that amount to hole filling. Formally, the semantics borrows machinery from both gradual type theory (which supplies the basis for handling unfilled type holes) and contextual modal type theory (which supplies a logical basis for hole closures), combining these and developing additional machinery necessary to continue evaluation past holes while maintaining type safety. We have mechanized the metatheory of the core calculus, called Hazelnut Live, using the Agda proof assistant. We have also implemented these ideas into the Hazel programming environment. The implementation inserts holes automatically, following the Hazelnut edit action calculus, to guarantee that every editor state has some (possibly incomplete) type. Taken together with this paper's type safety property, the result is a proof-of-concept live programming environment where rich dynamic feedback is truly available without gaps, i.e. for every reachable editor state.","tldr":"The semantics borrows machinery from both gradual type theory and contextual modal type theory, combining these and developing additional machinery necessary to continue evaluation past holes while maintaining type safety, and is a proof-of-concept live programming environment where rich dynamic feedback is truly available without gaps."},{"id":"doi:10.1145/3453483.3454059","doi":"10.1145/3453483.3454059","s2id":"98529f85b3ad96dfe2d5b047f66bac1484f80e9f","year":2021,"author":[{"ORCID":"http://orcid.org/0000-0003-4502-7971","authenticated-orcid":false,"given":"Cyrus","family":"Omar","sequence":"first","affiliation":[{"name":"University of Michigan, USA"}]},{"ORCID":"http://orcid.org/0000-0002-1081-2235","authenticated-orcid":false,"given":"David","family":"Moon","sequence":"additional","affiliation":[{"name":"University of Michigan, USA"}]},{"ORCID":"http://orcid.org/0000-0001-6938-7379","authenticated-orcid":false,"given":"Andrew","family":"Blinn","sequence":"additional","affiliation":[{"name":"University of Michigan, USA"}]},{"given":"Ian","family":"Voysey","sequence":"additional","affiliation":[{"name":"Carnegie Mellon University, USA"}]},{"ORCID":"http://orcid.org/0000-0001-6578-2005","authenticated-orcid":false,"given":"Nick","family":"Collins","sequence":"additional","affiliation":[{"name":"University of Chicago, USA"}]},{"ORCID":"http://orcid.org/0000-0002-1339-2889","authenticated-orcid":false,"given":"Ravi","family":"Chugh","sequence":"additional","affiliation":[{"name":"University of Chicago, USA"}]}],"title":"Filling typed holes with live GUIs: ","venue":"Proceedings of the 42nd ACM SIGPLAN International Conference on Programming Language Design and Implementation","url":"https://www.semanticscholar.org/paper/98529f85b3ad96dfe2d5b047f66bac1484f80e9f","abstract":"Text editing is powerful, but some types of expressions are more naturally represented and manipulated graphically. Examples include expressions that compute colors, music, animations, tabular data, plots, diagrams, and other domain-specific data structures. This paper introduces live literals, or livelits, which allow clients to fill holes of types like these by directly manipulating a user-defined GUI embedded persistently into code. Uniquely, livelits are compositional: a livelit GUI can itself embed spliced expressions, which are typed, lexically scoped, and can in turn embed other livelits. Livelits are also uniquely live: a livelit can provide continuous feedback about the run-time implications of the client’s choices even when splices mention bound variables, because the system continuously gathers closures associated with the hole that the livelit is filling. We integrate livelits into Hazel, a live hole-driven programming environment, and describe case studies that exercise these novel capabilities. We then define a simply typed livelit calculus, which specifies how livelits operate as live graphical macros. The metatheory of macro expansion has been mechanized in Agda.","tldr":"This paper introduces live literals, or livelits, which allow clients to fill holes of types like these by directly manipulating a user-defined GUI embedded persistently into code."},{"id":"doi:10.22152/programming-journal.org/2019/3/11","doi":"10.22152/programming-journal.org/2019/3/11","s2id":"160f3c45e133bc00e331ee38dfa933ca9ad11c31","year":2019,"author":[{"given":"Joe","family":"Politz","sequence":"first","affiliation":[{"name":"University of California San Diego, United States"}]},{"given":"Benjamin","family":"Lerner","sequence":"additional","affiliation":[{"name":"Northeastern University, United States"}]},{"given":"Sorawee","family":"Porncharoenwase","sequence":"additional","affiliation":[{"name":"Brown University, United States"}]},{"given":"Shriram","family":"Krishnamurthi","sequence":"additional","affiliation":[{"name":"Brown University, United States"}]}],"title":"Event Loops as First-Class Values: A Case Study in Pedagogic Language Design: ","venue":"The Art, Science, and Engineering of Programming","url":"https://www.semanticscholar.org/paper/160f3c45e133bc00e331ee38dfa933ca9ad11c31","abstract":"The World model is an existing functional input-output mechanism for event-driven programming. It is used in numerous popular textbooks and curricular settings. The World model conflates two different tasks -- the definition of an event processor and its execution -- into one. This conflation imposes a significant (even unacceptable) burden on student users in several educational settings where we have tried to use it, e.g., for teaching physics. While it was tempting to pile on features to address these issues, we instead used the Scheme language design dictum of removing weaknesses that made them seem necessary. By separating the two tasks above, we arrived at a slightly different primitive, the reactor, as our basis. This only defines the event processor, and a variety of execution operators dictate how it runs. The new design enables programmatic control over event-driven programs. This simplifies reflecting on program behavior, and eliminates many unnecessary curricular dependencies imposed by the old design. This work has been implemented in the Pyret programming language. The separation of concerns has enabled new curricula, such as the Bootstrap:Physics curriculum, to take flight. Thousands of students use this new mechanism every year. We believe that reducing impedance mismatches improves their educational experience.","tldr":"The World model is an existing functional input-output mechanism for event-driven programming that simplifies reflecting on program behavior, and eliminates many unnecessary curricular dependencies imposed by the old design, and has been implemented in the Pyret programming language."},{"id":"doi:10.22152/programming-journal.org/2019/3/9","doi":"10.22152/programming-journal.org/2019/3/9","s2id":"17ec1a022caebc5a1e0d64bff4cc36a7b2a526df","year":2019,"author":[{"given":"David","family":"Rauch","sequence":"first","affiliation":[{"name":"Hasso Plattner Institute, Germany"}]},{"given":"Patrick","family":"Rein","sequence":"additional","affiliation":[{"name":"Hasso Plattner Institute, Germany"}]},{"given":"Stefan","family":"Ramson","sequence":"additional","affiliation":[{"name":"Hasso Plattner Institute, Germany"}]},{"given":"Jens","family":"Lincke","sequence":"additional","affiliation":[{"name":"Hasso Plattner Institute, University of Potsdam, Germany"}]},{"given":"Robert","family":"Hirschfeld","sequence":"additional","affiliation":[{"name":"Hasso-Plattner-Institut (HPI), Germany"}]}],"title":"Babylonian-style Programming: Design and Implementation of an Integration of Live Examples into General-purpose Source Code: ","venue":"The Art, Science, and Engineering of Programming","url":"https://www.semanticscholar.org/paper/17ec1a022caebc5a1e0d64bff4cc36a7b2a526df","abstract":"When working on a program, developers traditionally have to simulate the behavior of the abstract code in their heads until they can execute the application. Live programming aims to support the development and comprehension of programs by providing more immediate feedback on program behavior, but the divide between code and behavior often remains. The goal of example-based live programming is to remove this gap by allowing programmers to explore the actual behavior of their code during development. This is achieved by defining live examples for parts of the application. The idea of live examples has been already addressed in other tools and environments. However, most of those solutions are limited to specific domains and are suitable only for small programs. Thus, we aim to extend the application of example-based live programming to more complex programs potentially spanning multiple modules. We investigate existing solutions to derive a set of requirements for an integration of live examples into source code. Based on these requirements we propose a new approach to live examples and present a prototype in its support. We reproduce, discuss, and extend scenarios from related work to show the practicality of our approach in the context of larger, more complicated, and with that also more realistic scenarios. Also, we measure and evaluate the system response time of our prototypical implementation. Our first results show that example-based live programming can provide more insights into the run-time behavior of parameterized code for non-trivial programs. They also reveal unsolved and new challenges affecting example-based live programming environments. In presenting this more general approach to example-based live programming, we hope to motivate further research into this area and to make practical solutions available.","tldr":"The first results show that example- based live programming can provide more insights into the run-time behavior of parameterized code for non-trivial programs and reveal unsolved and new challenges affecting example-based live programming environments."},{"id":"doi:10.22152/programming-journal.org/2019/3/1","doi":"10.22152/programming-journal.org/2019/3/1","s2id":"d46f8936a2fe30cb3d6a2ad00f95d03be6adecd1","year":2018,"author":[{"given":"Patrick","family":"Rein","sequence":"first","affiliation":[{"name":"Hasso Plattner Institute, Germany"}]},{"given":"Stefan","family":"Ramson","sequence":"additional","affiliation":[{"name":"Hasso Plattner Institute, Germany"}]},{"given":"Jens","family":"Lincke","sequence":"additional","affiliation":[{"name":"Hasso Plattner Institute, University of Potsdam, Germany"}]},{"given":"Robert","family":"Hirschfeld","sequence":"additional","affiliation":[{"name":"Hasso-Plattner-Institut (HPI), Germany"}]},{"given":"Tobias","family":"Pape","sequence":"additional","affiliation":[{"name":"Hasso Plattner Institute, Germany"}]}],"title":"Exploratory and Live, Programming and Coding: A Literature Study Comparing Perspectives on Liveness","venue":"The Art, Science, and Engineering of Programming","url":"https://www.semanticscholar.org/paper/d46f8936a2fe30cb3d6a2ad00f95d03be6adecd1","abstract":"Various programming tools, languages, and environments give programmers the impression of changing a program while it is running. This experience of liveness has been discussed for over two decades and a broad spectrum of research on this topic exists. Amongst others, this work has been carried out in the communities around three major ideas which incorporate liveness as an important aspect: live programming, exploratory programming, and live coding. While there have been publications on the focus of each particular community, the overall spectrum of liveness across these three communities has not been investigated yet. Thus, we want to delineate the variety of research on liveness. At the same time, we want to investigate overlaps and differences in the values and contributions between the three communities. \nTherefore, we conducted a literature study with a sample of 212 publications on the terms retrieved from three major indexing services. On this sample, we conducted a thematic analysis regarding the following aspects: motivation for liveness, application domains, intended outcomes of running a system, and types of contributions. We also gathered bibliographic information such as related keywords and prominent publications. \nBesides other characteristics the results show that the field of exploratory programming is mostly about technical designs and empirical studies on tools for general-purpose programming. In contrast, publications on live coding have the most variety in their motivations and methodologies with a majority being empirical studies with users. As expected, most publications on live coding are applied to performance art. Finally, research on live programming is mostly motivated by making programming more accessible and easier to understand, evaluating their tool designs through empirical studies with users. \nIn delineating the spectrum of work on liveness, we hope to make the individual communities more aware of the work of the others. Further, by giving an overview of the values and methods of the individual communities, we hope to provide researchers new to the field of liveness with an initial overview.","tldr":"A literature study with a sample of 212 publications on the terms retrieved from three major indexing services shows that the field of exploratory programming is mostly about technical designs and empirical studies on tools for general-purpose programming and publications on live coding have the most variety."},{"id":"doi:10.1109/TVCG.2018.2865158","doi":"10.1109/tvcg.2018.2865158","s2id":"b01c3150b37c318dc03c7663bade80e0a40275ad","year":2019,"author":[{"given":"Donghao","family":"Ren","sequence":"first","affiliation":[]},{"given":"Bongshin","family":"Lee","sequence":"additional","affiliation":[]},{"given":"Matthew","family":"Brehmer","sequence":"additional","affiliation":[]}],"title":"Charticulator: Interactive Construction of Bespoke Chart Layouts: ","venue":"IEEE Transactions on Visualization and Computer Graphics","url":"https://www.semanticscholar.org/paper/b01c3150b37c318dc03c7663bade80e0a40275ad","abstract":"We present Charticulator, an interactive authoring tool that enables the creation of bespoke and reusable chart layouts. Charticulator is our response to most existing chart construction interfaces that require authors to choose from predefined chart layouts, thereby precluding the construction of novel charts. In contrast, Charticulator transforms a chart specification into mathematical layout constraints and automatically computes a set of layout attributes using a constraint-solving algorithm to realize the chart. It allows for the articulation of compound marks or glyphs as well as links between these glyphs, all without requiring any coding or knowledge of constraint satisfaction. Furthermore, thanks to the constraint-based layout approach, Charticulator can export chart designs into reusable templates that can be imported into other visualization tools. In addition to describing Charticulator's conceptual framework and design, we present three forms of evaluation: a gallery to illustrate its expressiveness, a user study to verify its usability, and a click-count comparison between Charticulator and three existing tools. Finally, we discuss the limitations and potentials of Charticulator as well as directions for future research. Charticulator is available with its source code at https://charticulator.com.","tldr":"Charticulator is an interactive authoring tool that enables the creation of bespoke and reusable chart layouts and transforms a chart specification into mathematical layout constraints and automatically computes a set of layout attributes using a constraint-solving algorithm to realize the chart."},{"id":"doi:10.1111/cgf.12391","doi":"10.1111/cgf.12391","s2id":"dae2c3968fa06688cd99b2e024416dfcd50a36f7","year":2014,"author":[{"given":"Arvind","family":"Satyanarayan","sequence":"first","affiliation":[{"name":"Stanford University"}]},{"given":"Jeffrey","family":"Heer","sequence":"additional","affiliation":[{"name":"University of Washington"}]}],"title":"Lyra: An Interactive Visualization Design Environment: Lyra: An Interactive Visualization Design Environment","venue":"Computer Graphics Forum","url":"https://www.semanticscholar.org/paper/dae2c3968fa06688cd99b2e024416dfcd50a36f7","abstract":"We present Lyra, an interactive environment for designing customized visualizations without writing code. Using drag‐and‐drop interactions, designers can bind data to the properties of graphical marks to author expressive visualization designs. Marks can be moved, rotated and resized using handles; relatively positioned using connectors; and parameterized by data fields using property drop zones. Lyra also provides a data pipeline interface for iterative, visual specification of data transformations and layout algorithms. Visualizations created with Lyra are represented as specifications in Vega, a declarative visualization grammar that enables sharing and reuse. We evaluate Lyra's expressivity and accessibility through diverse examples and studies with journalists and visualization designers. We find that Lyra enables users to rapidly develop customized visualizations, covering a design space comparable to existing programming‐based tools.","tldr":"Lyra enables users to rapidly develop customized visualizations, covering a design space comparable to existing programming‐based tools, and is evaluated for its expressivity and accessibility."},{"id":"doi:10.1023/A:1008716330212","doi":"10.1023/a:1008716330212","s2id":"d857a39b5a421ace552e6a2f6c83977086fb982f","year":1999,"author":[{"given":"Frank M.","family":"Shipman","sequence":"first","affiliation":[]},{"given":"Catherine C.","family":"Marshall","sequence":"additional","affiliation":[]}],"title":"Formality Considered Harmful: Experiences, Emerging Themes, and Directions on the Use of Formal Representations in Interactive Systems: ","venue":"Computer Supported Cooperative Work (CSCW)","url":"https://www.semanticscholar.org/paper/d857a39b5a421ace552e6a2f6c83977086fb982f","tldr":"It is posed that, while it is impossible to remove all formalisms from computing systems, system designers need to match the level of formal expression entailed with the goals and situation of the users -- a design criteria not commonly mentioned in current interface design."},{"id":"doi:10.1016/S1045-926X(05)80012-6","doi":"10.1016/s1045-926x(05)80012-6","s2id":"0ba8fdbb23ca2ab15d2389cd68c10c410b467a70","year":1990,"author":[{"given":"Steven L.","family":"Tanimoto","sequence":"first","affiliation":[]}],"title":"VIVA: A visual language for image processing: ","venue":"Journal of Visual Languages &amp; Computing","url":"https://www.semanticscholar.org/paper/0ba8fdbb23ca2ab15d2389cd68c10c410b467a70","tldr":"VIVA is a proposed visual language for image processing that serves as an effective teaching tool for students of image processing and takes account of several secondary goals, including the completion of a software platform for research in human/image interaction and the establishment of a presentation medium for image-processing algorithms."},{"id":"Tanimoto:2013:PEL","doi":"10.1109/LIVE.2013.6617346","s2id":"cd95f3f397e967005d6f108d0dbf3c5c7ffbcce9","year":2013,"author":[{"given":"Steven L.","family":"Tanimoto"}],"title":"A Perspective on the Evolution of Live Programming","venue":"Proceedings of the 1st International Workshop on Live Programming","url":"https://www.semanticscholar.org/paper/cd95f3f397e967005d6f108d0dbf3c5c7ffbcce9","abstract":"Liveness in programming environments generally refers to the ability to modify a running program. Liveness is one form of a more general class of behaviors by a programming environment that provide information to programmers about what they are constructing. This paper gives a brief historical perspective on liveness and proposes an extension of a hierarchy given in 1990, to now account for even more powerful execution-oriented tools for programmers. In addition, while liveness concerns the timeliness of execution feedback, considering a broader array of forms of feedback is helpful both in better understanding liveness and in designing ever more powerful development tools.","tldr":"While liveness concerns the timeliness of execution feedback, considering a broader array of forms of feedback is helpful both in better understanding liveness and in designing ever more powerful development tools."},{"id":"doi:10.1145/3025453.3025768","doi":"10.1145/3025453.3025768","s2id":"6a5003f5ae44c94401b93513e23ceb17922be3c4","year":2017,"author":[{"given":"Kanit","family":"Wongsuphasawat","sequence":"first","affiliation":[{"name":"University of Washington, Seattle, WA, USA"}]},{"given":"Zening","family":"Qu","sequence":"additional","affiliation":[{"name":"University of Washington, Seattle, WA, USA"}]},{"given":"Dominik","family":"Moritz","sequence":"additional","affiliation":[{"name":"University of Washington, Seattle, WA, USA"}]},{"given":"Riley","family":"Chang","sequence":"additional","affiliation":[{"name":"University of Washington, Seattle, WA, USA"}]},{"given":"Felix","family":"Ouk","sequence":"additional","affiliation":[{"name":"University of Washington, Seattle, WA, USA"}]},{"given":"Anushka","family":"Anand","sequence":"additional","affiliation":[{"name":"Tableau Research, Seattle, WA, USA"}]},{"given":"Jock","family":"Mackinlay","sequence":"additional","affiliation":[{"name":"Tableau Software, Seattle, WA, USA"}]},{"given":"Bill","family":"Howe","sequence":"additional","affiliation":[{"name":"University of Washington, Seattle, WA, USA"}]},{"given":"Jeffrey","family":"Heer","sequence":"additional","affiliation":[{"name":"University of Washington, Seattle, WA, USA"}]}],"title":"Voyager 2: Augmenting Visual Analysis with Partial View Specifications","venue":"Proceedings of the 2017 CHI Conference on Human Factors in Computing Systems","url":"https://www.semanticscholar.org/paper/6a5003f5ae44c94401b93513e23ceb17922be3c4","abstract":"Visual data analysis involves both open-ended and focused exploration. Manual chart specification tools support question answering, but are often tedious for early-stage exploration where systematic data coverage is needed. Visualization recommenders can encourage broad coverage, but irrelevant suggestions may distract users once they commit to specific questions. We present Voyager 2, a mixed-initiative system that blends manual and automated chart specification to help analysts engage in both open-ended exploration and targeted question answering. We contribute two partial specification interfaces: wildcards let users specify multiple charts in parallel, while related views suggest visualizations relevant to the currently specified chart. We present our interface design and applications of the CompassQL visualization query language to enable these interfaces. In a controlled study we find that Voyager 2 leads to increased data field coverage compared to a traditional specification tool, while still allowing analysts to flexibly drill-down and answer specific questions.","tldr":"This work presents Voyager 2, a mixed-initiative system that blends manual and automated chart specification to help analysts engage in both open-ended exploration and targeted question answering and contributes two partial specification interfaces."},{"id":"bootstrap","year":2022,"author":[{"family":"Bootstrap"}],"title":"Bootstrap","url":"https://bootstrapworld.org/index.shtml"},{"id":"cuttle","year":2022,"author":[{"family":"Cuttle Labs Inc."}],"title":"Cuttle - Design tool for digital cutting machines","url":"https://cuttle.xyz/"},{"id":"enso","year":2022,"author":[{"family":"Enso"}],"title":"Enso","url":"https://enso.org/"},{"id":"everest","year":2021,"author":[{"given":"Everest","family":"Pipkin"}],"title":"been having some  motivation troubles  recently (god who hasn't) so i'm gonna pick a tiny personal project off my ideas list and see if i can get it working by morning. tonight - a lil bash script that emails me the summaries of 5 random wikipedia articles each morning","url":"https://twitter.com/everestpipkin/status/1349274983651012609"},{"id":"image-based","year":2021,"author":[{"given":"Jonathan","family":"Edwards"},{"given":"Tomas","family":"Petricek"}],"title":"Typed Image-based Programming with Structure Editing","url":"https://arxiv.org/abs/2110.08993"},{"id":"inventing-on-principle","year":2012,"author":[{"given":"Bret","family":"Victor"}],"title":"Inventing on Principle","url":"https://vimeo.com/36579366"},{"id":"lamdu","year":2022,"author":[{"given":"Eyal","family":"Lotem"},{"given":"Yair","family":"Chuchem"}],"title":"Lamdu","url":"https://www.lamdu.org/"},{"id":"learnable-programming","year":2012,"author":[{"given":"Bret","family":"Victor"}],"title":"Learnable Programming","url":"http://worrydream.com/LearnableProgramming/"},{"id":"light-table","year":2022,"author":[{"given":"Chris","family":"Granger"}],"title":"Light Table","url":"http://lighttable.com/"},{"id":"live-literals","year":2016,"author":[{"given":"Tijs","family":"Storm","non-dropping-particle":"van der"},{"given":"Felienne","family":"Hermans"}],"title":"Live Literals","url":"https://homepages.cwi.nl/~storm/livelit/livelit.html"},{"id":"mps","year":2022,"author":[{"family":"JetBrains s.r.o."}],"title":"MPS: The Domain-Specific Language Creator by JetBrains","url":"https://www.jetbrains.com/mps/"},{"id":"natto","year":2022,"author":[{"given":"Paul","family":"Shen"}],"title":"welcome! – natto","url":"https://natto.dev/"},{"id":"natto-hn","year":2021,"author":[{"given":"Paul","family":"Shen"}],"title":"Show HN: Natto – a canvas for writing and manipulating JavaScript","url":"https://news.ycombinator.com/item?id=26478548"},{"id":"observable","year":2022,"author":[{"family":"Observable Inc."}],"title":"Observable - Explore, analyze, and explain data. As a team.","url":"https://observablehq.com/"},{"id":"observable-data-table-cell","year":2022,"author":[{"family":"Observable Inc."}],"title":"Quickly Explore & Analyze Your Data With Data Table Cell / Observable / Observable","url":"https://observablehq.com/@observablehq/introducing-data-table-cell"},{"id":"pane","year":2018,"author":[{"given":"Joshua","family":"Horowitz"}],"title":"PANE: Programming with Visible Data","url":"http://joshuahhh.com/projects/pane/"},{"id":"react","year":2022,"author":[{"family":"Meta Platforms, Inc."}],"title":"React – A JavaScript library for building user interfaces","url":"https://reactjs.org/"},{"id":"restructuring-structured-editing","year":2021,"author":[{"given":"David","family":"Moon"},{"given":"Cyrus","family":"Omar"}],"title":"Restructuring Structure Editing","url":"https://tylr.fun/essay/"},{"id":"seymour","year":2017,"author":[{"given":"Saketh","family":"Kasibatla"},{"given":"Alex","family":"Warth"}],"title":"Seymour: Live Programming for the Classroom","url":"https://harc.github.io/seymour-live2017/"},{"id":"swift-playgrounds","year":2014,"author":[{"family":"Apple Inc."}],"title":"WWDC 2014","url":"https://www.youtube.com/watch?v=w87fOAG8fjk"},{"id":"wikipedia-grafting","year":2022,"author":[{"family":"Wikipedia contributors"}],"title":"Grafting — Wikipedia, The Free Encyclopedia","url":"https://en.wikipedia.org/w/index.php?title=Grafting&oldid=1095365064"},{"id":"yoshiki","year":2019,"author":[{"given":"Yoshiki","family":"Schmitz"}],"title":"I've been jamming on this concept for making data-driven designs...","url":"https://twitter.com/yoshikischmitz/status/1176642448077967362"}]);
};
